def construct():
    p = 17
    # Quadratic residues modulo 17
    # 1^2=1, 2^2=4, 3^2=9, 4^2=16, 5^2=8, 6^2=2, 7^2=15, 8^2=13
    # Q = {1, 2, 4, 8, 9, 13, 15, 16}
    residues = set()
    for i in range(1, p):
        residues.add((i * i) % p)
    
    # Construct the base vector for the circulant generator matrix
    # The QR code of length p is generated by the circulant matrix with first row v
    # where v_i = 1 if i is in Q (for i=1..p-1) and v_0 = 0? 
    # Actually, the standard QR code generator matrix has 1s at quadratic residue positions.
    # Let's verify the dimension. It should be (p+1)/2 = 9.
    
    # The vector v of length p
    v = [0] * p
    for r in residues:
        v[r] = 1
        
    # The generator matrix G is p x p circulant, but the code is the row space of a (p+1)/2 x p matrix?
    # No, the QR code is a subcode of the simplex code?
    # The QR code is generated by the circulant matrix C with first row v.
    # The rank of C is (p+1)/2.
    # We need to extract a basis of the rowspace.
    
    # To get the basis, we can just take the first (p+1)/2 rows of the circulant matrix.
    # Are they linearly independent? Yes, for QR codes.
    
    k = (p + 1) // 2
    G = []
    for i in range(k):
        # Row i is the base vector shifted by i
        row = [0] * p
        for j in range(p):
            # Shift right by i (or left, doesn't matter for span)
            # Let's shift right: v[(j - i) % p]
            row[j] = v[(j - i) % p]
        G.append(row)
        
    # Now generate all 2^k codewords
    codewords = []
    for mask in range(1 << k):
        word = 0
        for i in range(k):
            if (mask >> i) & 1:
                # XOR the row i into word
                # Row i is G[i]
                # We need to convert G[i] to an integer or XOR bit by bit
                # It's faster to precompute the rows as integers
                pass
        
    # Optimization: Precompute rows as integers
    rows_int = []
    for i in range(k):
        row_val = 0
        for j in range(p):
            if G[i][j]:
                row_val |= (1 << j)
        rows_int.append(row_val)
        
    for mask in range(1 << k):
        word = 0
        for i in range(k):
            if (mask >> i) & 1:
                word ^= rows_int[i]
        
        # Extend by parity bit
        # The extended QR code adds a parity check bit to ensure even weight.
        parity = word.bit_count() % 2
        # Append parity bit at position p (which is 17)
        word |= (parity << p)
        
        codewords.append(word)
        
    return codewords
